protected setRedate(id: number, date: string): void {
  this.redates.update((dates) => ({ ...dates, [id]: date }));
  this.clearRowError(id);
}

/** Re-date the claim to the date typed on its row; only a steward can re-date an OPEN or PENDING
 *  claim, neither it nor the new date in a closed period and the new date not after its person's
 *  retirement, so anything else is refused with an error. */
protected async redate(claim: Claim): Promise<void> {
  this.clearRowError(claim.id);
  const sheet = this.session.sheetId();
  if (!sheet) return;
  const date = (this.redates()[claim.id] ?? '').trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    this.rowErrors.update((errors) => ({ ...errors, [claim.id]: 'Choose the date to re-date that claim to.' }));
    return;
  }
  try {
    const changed = await this.service.redate(sheet, claim.id, date);
    if (this.session.sheetId() !== sheet) return;
    this.redates.update(({ [claim.id]: _, ...rest }) => rest);
    this.saved.emit(changed);
  } catch (e) {
    if (this.session.sheetId() !== sheet) return;
    const status = e instanceof HttpErrorResponse ? e.status : 0;
    this.rowErrors.update((errors) => ({
      ...errors,
      [claim.id]: status === 403
        ? 'Only a steward can re-date a claim.'
        : status === 423
        ? 'Neither the claim nor its new date can be in a closed period.'
        : status === 409
        ? "A claim cannot be dated after its person's retirement."
        : 'Only an open or pending claim can be re-dated.',
    }));
    if (selected) next.add(id);
    else next.delete(id);
    return next;
  });
}

/** Open the selected claims together, numbered in list order; those that cannot be opened are left
 *  as they are. Shows how many were opened and refused; the old counts are gone while it runs. */
protected async bulkOpen(): Promise<void> {
  const sheet = this.session.sheetId();
  if (!sheet || this.bulkOpening) return;
  this.bulkOpened.set(null);
  this.bulkOpening = true;
  try {
    const result = await this.claimsService.bulkOpen(sheet, [...this.selectedClaims()]);
    if (this.session.sheetId() !== sheet) return;
    for (const c of result.claims) this.claimSaved(c);
    this.selectedClaims.set(new Set());
    this.bulkOpened.set({ opened: result.opened, refused: result.refused });
  } catch {
    if (this.session.sheetId() === sheet) this.bulkOpened.set({ opened: 0, refused: this.selectedClaims().size });
  } finally {
    this.bulkOpening = false;
  }
}

/** Settle the selected claims together, in list order, each by the rules of settling one, all or
 *  nothing: if any cannot be settled, none is. Shows how many were settled and refused; the old

